 const nativeInfo=logger.info.bind(logger);const logs:any[]=[];t.mock.method(logger,'info',(_label:string,value:any)=>{logs.push(value);nativeInfo(_label,value);});
 let HTTPcalls=0;const HTTPHeaders:any[]=[];const HTTPBodies:any[]=[];let resolveHTTP!:(value:any)=>void;
