 clock=0;startTransportEvent(eventA);
 clock=10;const apiA=withEventContext(eventA,()=>{},()=>requestBackend(eventA.UserId,'get_players_id_storyline_catalog',{path:{id:1},query:{page:1}}));
 clock=20;let fileDone!:(value:string)=>void;const fileA=measureTransportStage('image.file_load',()=>new Promise<string>(r=>{fileDone=r}),eventA);
 clock=30;resolveHTTP({status:200,headers:{},data:'{"data":{"ok":true}}'});assert.deepEqual(await apiA,{ok:true});
 clock=35;let sendDone!:(value:any)=>void;const receipts=[{code:4000,message:'PRIVATE-RECEIPT',data:'PRIVATE-DATA'}];const params:any=measureTransportStageSync('response.build',()=>{clock=40;return {format:[]}},eventA);
 const client=timedMessageClient({send:async(p:any)=>{assert.equal(p,params);return new Promise(r=>{sendDone=r});}} as any,eventA);
 const sendA=client.send(params);
 clock=40;fileDone('same-bytes');assert.equal(await fileA,'same-bytes');clock=60;sendDone(receipts);assert.equal(await sendA,receipts);
 clock=0;startTransportEvent(eventB);clock=10;const apiB=withEventContext(eventB,()=>{},()=>requestBackend(eventB.UserId,'get_players_id_shop_products',{path:{id:1},query:{page:1}}));clock=35;resolveHTTP({status:200,headers:{},data:'{"data":{"ok":true}}'});await apiB;
 clock=40;const sendB=measureTransportStage('platform.send',async()=>{clock=70;return 'same-result'},eventB);assert.equal(await sendB,'same-result');
 assert.equal(HTTPcalls,2);assert.equal(HTTPHeaders[0]['x-request-id'],authorityA.requestId);assert.equal(HTTPHeaders[1]['x-request-id'],authorityB.requestId);assert.equal(HTTPHeaders[0]['idempotency-key'],undefined);
 const out=analyzeBotTimings(logs.map(x=>JSON.stringify(x)).join('\n'));assert.equal(out.samples.length,2);const a=out.samples.find((x:any)=>x.commandKey==='storyline.list'),b=out.samples.find((x:any)=>x.commandKey==='shop.list');assert.ok(a&&b);assert.equal(a.requestId,b.requestId);assert.notEqual(a.eventTraceId,b.eventTraceId);assert.equal(a.observedLastSendEndMs,60);assert.equal(a.measuredWindowUnionMs,50);assert.equal(a.phases['file-preparation'].unionMs,20);assert.equal(a.phases['response-build'].unionMs,5);assert.equal(a.phases['response-build'].observedSendWindowUnionMs,5);assert.equal(a.sendState,'send-promise-fulfilled-receipt-and-display-unknown');assert.equal(b.observedLastSendEndMs,70);
 const legacy=analyzeBotTimings(logs.map(({eventTraceId,commandKey,...x})=>JSON.stringify(x)).join('\n'));assert.equal(legacy.samples.length,1);assert.equal(legacy.samples[0].ambiguousIdentity,true);assert.equal(legacy.samples[0].observedLastSendEndMs,null);
 const fileOnlyStart=logs.length;const fileOnly:any={...eventA,MessageText:'/unknown PRIVATE-ARG'};
